import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format loosely
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column whitelist - but filter is not validated
        String safeSortCol = "created_at";
        if (sortCol != null && sortCol.matches("(created_at|amount|customer_name|status)")) {
            safeSortCol = sortCol;
        }

        String query = buildQuery(reportType, startDate, endDate, safeSortCol, customFilter);
        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("text/csv");
            resp.setHeader("Content-Disposition", "attachment; filename=report.csv");
            PrintWriter out = resp.getWriter();

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            for (int i = 1; i <= cols; i++) {
                out.print(meta.getColumnName(i));
                if (i < cols) out.print(",");
            }
            out.println();

            while (rs.next()) {
                for (int i = 1; i <= cols; i++) {
                    String val = rs.getString(i);
                    out.print(val != null ? "\"" + val.replace("\"", "\"\"") + "\"" : "");
                    if (i < cols) out.print(",");
                }
                out.println();
            }
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildQuery(String reportType, String startDate, String endDate,
                              String sortCol, String customFilter) {
        String table;
        switch (reportType) {
            case "sales": table = "sales_transactions"; break;
            case "refunds": table = "refund_transactions"; break;
            case "inventory": table = "inventory_log"; break;
            default: table = "sales_transactions";
        }

        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM ").append(table);
        sb.append(" WHERE created_at >= '").append(startDate).append("'");
        sb.append(" AND created_at <= '").append(endDate).append("'");

        // Custom filter allows flexible reporting - appended directly
        if (customFilter != null && !customFilter.isEmpty()) {
            sb.append(" AND ").append(customFilter);
        }

        sb.append(" ORDER BY ").append(sortCol).append(" DESC");
        sb.append(" LIMIT 10000");
        return sb.toString();
    }
}
